#!/usr/bin/env bash
# Derive the broker-free catalogue CI entrypoint from the production auto-merge workflow.
# Pull-request CI may not grant id-token: write (.github/tests/test-ci-idtoken-boundary.sh), and
# GitHub refuses a call whose caller grants less than a called job asks for, even when that job
# never runs. So catalogue CI calls this projection instead: production with its display name
# changed, only its workflow_call trigger kept (so it never runs on its own), and the auto-merge
# job's id-token grant removed. Its dry-run job is exactly production's, and nothing in it can
# reach the GitHub token broker.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
source="${1:-$root/.github/workflows/enable-auto-merge.yaml}"
destination="${2:-$root/.github/workflows/enable-auto-merge-dry-run.yaml}"
work="$(mktemp)"
trap 'rm -f "$work"' EXIT
yq '
  .name = "🔀 Enable Auto-Merge (Dry-Run CI)" |
  .on = {"workflow_call": .on.workflow_call} |
  del(.jobs["auto-merge"].permissions["id-token"])
' "$source" >"$work"
{
  printf '# Generated by .github/scripts/generate-enable-auto-merge-dry-run.sh; do not edit.\n'
  cat "$work"
} >"$destination"
